ALTER TABLE character_cosmetics ADD COLUMN price_diamonds BIGINT NOT NULL DEFAULT 0, ADD COLUMN collection_id TEXT, ADD COLUMN version INT NOT NULL DEFAULT 1, ADD COLUMN starts_at TIMESTAMPTZ(3), ADD COLUMN ends_at TIMESTAMPTZ(3);
ALTER TABLE character_cosmetics DROP CONSTRAINT cosmetic_valid;
ALTER TABLE character_cosmetics ADD CONSTRAINT cosmetic_valid CHECK (slot IN ('HEADWEAR','HAIR','UPPER','LOWER','SHOES','BELT','FACE_ACCESSORY','BACK','OUTERWEAR','NECKLACE','WRIST','HANDHELD','DYE','PATTERN') AND min_level>0 AND price_gold>=0 AND price_diamonds>=0 AND unlock_type IN ('FREE','LEVEL','GOLD','DIAMOND') AND (ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at) AND version>0);
ALTER TABLE wallets ADD COLUMN balance_diamonds BIGINT NOT NULL DEFAULT 0 CHECK (balance_diamonds BETWEEN 0 AND 9000000000000);
CREATE TABLE diamond_transactions (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE, amount BIGINT NOT NULL CHECK(amount<>0), balance_after BIGINT NOT NULL CHECK(balance_after>=0), reason TEXT NOT NULL, reference TEXT UNIQUE NOT NULL, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE INDEX diamond_transactions_user_id_created_at_idx ON diamond_transactions(user_id,created_at);
CREATE TRIGGER diamond_ledger_immutable BEFORE UPDATE OR DELETE ON diamond_transactions FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TABLE player_outfits(id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE, name VARCHAR(40) NOT NULL, appearance JSONB NOT NULL, equipment JSONB NOT NULL, is_public BOOLEAN NOT NULL DEFAULT FALSE, version INT NOT NULL DEFAULT 1, updated_at TIMESTAMPTZ(3) NOT NULL);
CREATE INDEX player_outfits_user_id_updated_at_idx ON player_outfits(user_id,updated_at);
CREATE INDEX player_outfits_is_public_updated_at_idx ON player_outfits(is_public,updated_at);
CREATE TABLE outfit_likes(outfit_id UUID NOT NULL REFERENCES player_outfits(id) ON DELETE CASCADE ON UPDATE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE, PRIMARY KEY(outfit_id,user_id));
CREATE TABLE fashion_follows(user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE, target_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE, PRIMARY KEY(user_id,target_id), CHECK(user_id<>target_id));
CREATE TABLE fashion_collections(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,item_ids JSONB NOT NULL,discount_percent INT NOT NULL CHECK(discount_percent BETWEEN 0 AND 50),active BOOLEAN NOT NULL DEFAULT TRUE,version INT NOT NULL DEFAULT 1);
CREATE TABLE fashion_events(id UUID PRIMARY KEY,name TEXT NOT NULL,theme TEXT NOT NULL,starts_at TIMESTAMPTZ(3) NOT NULL,ends_at TIMESTAMPTZ(3) NOT NULL,reward_gold BIGINT NOT NULL CHECK(reward_gold BETWEEN 0 AND 1000000),reward_cosmetic_id TEXT REFERENCES character_cosmetics(id) ON DELETE RESTRICT ON UPDATE CASCADE,active BOOLEAN NOT NULL DEFAULT FALSE,version INT NOT NULL DEFAULT 1,CHECK(starts_at<ends_at));
CREATE TABLE fashion_event_entries(id UUID PRIMARY KEY,event_id UUID NOT NULL REFERENCES fashion_events(id) ON DELETE RESTRICT ON UPDATE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE,outfit_snapshot JSONB NOT NULL,claimed_at TIMESTAMPTZ(3),UNIQUE(event_id,user_id));
CREATE TABLE fashion_event_votes(event_id UUID NOT NULL REFERENCES fashion_events(id) ON DELETE RESTRICT ON UPDATE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE,entry_id UUID NOT NULL REFERENCES fashion_event_entries(id) ON DELETE RESTRICT ON UPDATE CASCADE,PRIMARY KEY(event_id,user_id));
UPDATE character_cosmetics SET collection_id='elder' WHERE id IN ('elder-upper','elder-lower');
UPDATE character_cosmetics SET collection_id='wanderer' WHERE id IN ('wanderer-upper','wanderer-lower');
UPDATE character_cosmetics SET collection_id='maiden' WHERE id IN ('maiden-upper','maiden-lower');
UPDATE character_cosmetics SET collection_id='fisher' WHERE id IN ('fisher-upper','fisher-lower');
UPDATE character_cosmetics SET collection_id='royal' WHERE id IN ('royal-upper','royal-lower');
UPDATE character_cosmetics SET collection_id='taoist' WHERE id IN ('taoist-upper','taoist-lower');
